// Новые сверху. Курсор: (published_at, id) последней строки предыдущей страницы.
func (q *Queries) ListLibraryNewest(ctx context.Context, arg ListLibraryNewestParams) ([]LibraryItem, error) {
	rows, err := q.db.Query(ctx, listLibraryNewest,
		arg.LibrarySubjectID,
		arg.Kind,
		arg.Semester,
		arg.CursorPublishedAt,
		arg.CursorID,
		arg.PageSize,
	)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []LibraryItem
	for rows.Next() {
		var i LibraryItem
		if err := rows.Scan(
			&i.ID,
			&i.UserID,
			&i.Title,
			&i.Summary,
			&i.Kind,
			&i.Semester,
			&i.PublishedAt,
			&i.Views,
			&i.LibrarySubjectID,
			&i.SubjectTitle,
			&i.SubjectColor,
			&i.AuthorName,
			&i.AuthorFaculty,
			&i.RatingCount,
			&i.RatingAvg,
			&i.CommentsCount,
			&i.BookmarksCount,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

const listLibrarySubjects = `-- name: ListLibrarySubjects :many

SELECT ls.id, ls.title, ls.color, ls.created_at,
       (SELECT count(*) FROM notes n
         WHERE n.library_subject_id = ls.id AND n.status = 'published' AND n.deleted_at IS NULL)::bigint AS materials_count
FROM library_subjects ls
ORDER BY lower(ls.title)
`

type ListLibrarySubjectsRow struct {
	ID             uuid.UUID   `json:"id"`
	Title          string      `json:"title"`
	Color          pgtype.Text `json:"color"`
	CreatedAt      time.Time   `json:"created_at"`
	MaterialsCount int64       `json:"materials_count"`
}

// ---------------------------------------------------------------------------
