const listViewerState = `-- name: ListViewerState :many
SELECT n.id AS note_id,
       r.value AS my_rating,
       EXISTS (SELECT 1 FROM note_bookmarks b WHERE b.note_id = n.id AND b.user_id = $1)::boolean AS bookmarked
FROM notes n
LEFT JOIN note_ratings r ON r.note_id = n.id AND r.user_id = $1
WHERE n.id = ANY($2::uuid[])
`

type ListViewerStateParams struct {
	ViewerID uuid.UUID   `json:"viewer_id"`
	NoteIds  []uuid.UUID `json:"note_ids"`
}

type ListViewerStateRow struct {
	NoteID     uuid.UUID   `json:"note_id"`
	MyRating   pgtype.Int2 `json:"my_rating"`
	Bookmarked bool        `json:"bookmarked"`
}

// Личное состояние зрителя для набора материалов: его оценка и отметка «в избранном».
func (q *Queries) ListViewerState(ctx context.Context, arg ListViewerStateParams) ([]ListViewerStateRow, error) {
	rows, err := q.db.Query(ctx, listViewerState, arg.ViewerID, arg.NoteIds)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []ListViewerStateRow
	for rows.Next() {
		var i ListViewerStateRow
		if err := rows.Scan(&i.NoteID, &i.MyRating, &i.Bookmarked); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

const rejectNote = `-- name: RejectNote :one
UPDATE notes SET status = 'rejected', published_at = NULL
WHERE id = $1 AND status = 'pending' AND deleted_at IS NULL
RETURNING id, user_id, subject_id, title, content, content_text, is_pinned, created_at, updated_at, deleted_at, kind, summary, semester, status, published_at, views, library_subject_id
`

